 24	public class Main {
 25	
 26	    public static void main(String[] args) {
 27	        DataSource dataSource = createDataSource();
 28	        DatabaseInitializer.initialize(dataSource);
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dataSource);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 32	        MessageRepository messageRepository = new MessageRepository(dataSource);
 33	
 34	        PricingService pricingService = new PricingService();
 35	        DocumentService documentService = new DocumentService();
 36	        EmailService emailService = new EmailService(messageRepository);
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository, roomRepository, pricingService, documentService, emailService
 39	        );
 40	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 41	
 42	        int port = getPort();
 43	
 44	        Javalin app = Javalin.create(config -> {
 45	            ObjectMapper mapper = new ObjectMapper();
 46	            mapper.registerModule(new JavaTimeModule());
 47	            mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 48	            mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
 49	            config.jsonMapper(new JavalinJackson(mapper, true));
 50	        });
 51	
 52	        app.exception(ApiException.class, (e, ctx) -> {
 53	            ctx.status(e.getStatusCode());
 54	            ctx.json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
 55	        });
 56	
 57	        app.exception(Exception.class, (e, ctx) -> {
 58	            e.printStackTrace();
 59	            ctx.status(400);
 60	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 61	        });
 62	
 63	        app.get("/rooms", ctx -> {
 64	            var rooms = roomRepository.findAll();
 65	            ctx.json(rooms.stream().map(RoomResponse::from).toList());
 66	        });
 67	
 68	        app.post("/reservations", ctx -> {
 69	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 70	            validateRequest(request);
 71	
 72	            var reservation = reservationService.createReservation(request.toReservation());
 73	            ctx.status(201);
 74	            ctx.json(ReservationResponse.from(reservation));
 75	        });
 76	
 77	        app.get("/reservations/{id}", ctx -> {
 78	            Long id = ctx.pathParamAsClass("id", Long.class).get();
 79	            var reservation = reservationService.getReservation(id);
 80	            ctx.json(ReservationResponse.from(reservation));
 81	        });
 82	
 83	        app.post("/reservations/{id}/confirmation", ctx -> {
 84	            Long id = ctx.pathParamAsClass("id", Long.class).get();
 85	            var reservation = reservationService.confirmReservation(id);
 86	            ctx.json(ReservationResponse.from(reservation));
 87	        });
 88	
 89	        app.post("/reservations/{id}/check-in", ctx -> {
 90	            Long id = ctx.pathParamAsClass("id", Long.class).get();
 91	            var reservation = reservationService.checkIn(id);
 92	            ctx.json(ReservationResponse.from(reservation));
 93	        });
 94	
 95	        app.post("/reservations/{id}/check-out", ctx -> {
 96	            Long id = ctx.pathParamAsClass("id", Long.class).get();
 97	            Document document = reservationService.checkOut(id);
 98	            ctx.json(document);
 99	        });
100	
101	        app.post("/reservations/{id}/cancellation", ctx -> {
102	            Long id = ctx.pathParamAsClass("id", Long.class).get();
103	            var reservation = reservationService.cancelReservation(id);
104	            ctx.json(ReservationResponse.from(reservation));
105	        });
106	
107	        app.get("/reservations/{id}/document", ctx -> {
108	            Long id = ctx.pathParamAsClass("id", Long.class).get();
109	            Document document = reservationService.getDocument(id);
110	            ctx.json(document);
111	        });
112	
113	        app.get("/messages", ctx -> {
114	            var messages = messageRepository.findAll();
115	            ctx.json(messages);
116	        });
117	
118	        app.get("/reports/occupancy", ctx -> {
119	            String dateStr = ctx.queryParam("date");
120	            if (dateStr == null) {
121	                throw ApiException.invalidRequest("Date parameter is required");
122	            }
123	
124	            LocalDate date = parseDate(dateStr);
125	            String csv = reportService.generateOccupancyReport(date);
126	            ctx.contentType("text/csv; charset=utf-8");
127	            ctx.result(csv);
128	        });
129	
130	        app.get("/reports/revenue", ctx -> {
131	            String monthStr = ctx.queryParam("month");
132	            if (monthStr == null) {
133	                throw ApiException.invalidRequest("Month parameter is required");
134	            }
135	
136	            YearMonth month = parseMonth(monthStr);
137	            String csv = reportService.generateRevenueReport(month);
138	            ctx.contentType("text/csv; charset=utf-8");
139	            ctx.result(csv);
140	        });
141	
142	        app.start(port);
143	        System.out.println("Pousada Maré Alta server started on port " + port);
144	    }
