146	    private static DataSource createDataSource() {
147	        String dbUrl = System.getenv("DB_URL");
148	        String dbUser = System.getenv("DB_USER");
149	        String dbPassword = System.getenv("DB_PASSWORD");
150	
151	        if (dbUrl == null || dbUser == null || dbPassword == null) {
152	            throw new RuntimeException("Database environment variables not set");
153	        }
154	
155	        PGSimpleDataSource ds = new PGSimpleDataSource();
156	        ds.setURL(dbUrl);
157	        ds.setUser(dbUser);
158	        ds.setPassword(dbPassword);
159	
160	        return ds;
161	    }
162	
163	    private static int getPort() {
164	        String portStr = System.getenv("PORT");
165	        return portStr != null ? Integer.parseInt(portStr) : 7070;
166	    }
167	
168	    private static void validateRequest(CreateReservationRequest request) {
169	        if (request.getRoomNumber() == null || request.getGuestName() == null ||
170	            request.getGuestEmail() == null || request.getCheckIn() == null ||
171	            request.getCheckOut() == null || request.getRatePlan() == null) {
172	            throw ApiException.invalidRequest("Missing required fields");
173	        }
174	    }
175	
176	    private static LocalDate parseDate(String dateStr) {
177	        try {
178	            return LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
179	        } catch (DateTimeParseException e) {
180	            throw ApiException.invalidRequest("Invalid date format. Expected: yyyy-MM-dd");
181	        }
182	    }
183	
184	    private static YearMonth parseMonth(String monthStr) {
185	        try {
186	            return YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
187	        } catch (DateTimeParseException e) {
188	            throw ApiException.invalidRequest("Invalid month format. Expected: yyyy-MM");
189	        }
190	    }
191	}
