201	public class DocumentService {
202	
203	    private static final DateTimeFormatter PT_DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
204	    private static final DateTimeFormatter EN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
205	    private static final BigDecimal ISS_RATE = new BigDecimal("0.05");
206	
207	    public Document generateDocument(Reservation reservation, Room room) {
208	        Document doc = new Document();
209	        doc.setReservationId(reservation.getId());
210	        doc.setGuestName(reservation.getGuestName());
211	        doc.setRoomNumber(room.getNumber());
212	        doc.setRoomType(room.getType());
213	        doc.setCheckIn(reservation.getCheckIn());
214	        doc.setCheckOut(reservation.getCheckOut());
215	        doc.setNights(reservation.getNights());
216	        doc.setSubtotal(reservation.getSubtotal());
217	        doc.setDiscount(reservation.getDiscount());
218	        doc.setTotal(reservation.getTotal());
219	
220	        GuestIdentification id = reservation.getIdentification();
221	        doc.setGuestCpf(id.getGuestCpf());
222	        doc.setCompanyCnpj(id.getCompanyCnpj());
223	        doc.setCompanyName(id.getCompanyName());
224	        doc.setGuestPassport(id.getGuestPassport());
225	        doc.setGuestCountry(id.getGuestCountry());
226	
227	        if (id.isCpf()) {
228	            generateReceipt(doc);
229	        } else if (id.isCompany()) {
230	            generateInvoice(doc);
231	        } else if (id.isPassport()) {
232	            generateBookingReceipt(doc);
233	        }
234	
235	        return doc;
236	    }
237	
238	    private void generateReceipt(Document doc) {
239	        doc.setTitle("Comprovante de reserva");
240	
241	        StringBuilder text = new StringBuilder();
242	        text.append("Comprovante de reserva nº ").append(doc.getReservationId()).append("\n");
243	        text.append("Hóspede: ").append(doc.getGuestName());
244	        text.append(" (CPF ").append(doc.getGuestCpf()).append(")\n");
245	        text.append("Quarto: ").append(doc.getRoomNumber());
246	        text.append(" (").append(doc.getRoomType()).append(")\n");
247	        text.append("Entrada: ").append(doc.getCheckIn().format(PT_DATE_FORMAT));
248	        text.append(" | Saída: ").append(doc.getCheckOut().format(PT_DATE_FORMAT));
249	        text.append(" | ").append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
250	        text.append("Diárias: ").append(MoneyUtils.formatBRL(doc.getSubtotal())).append("\n");
251	
252	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
253	            text.append("Desconto: ").append(MoneyUtils.formatBRL(doc.getDiscount())).append("\n");
254	        }
255	
256	        text.append("Total: ").append(MoneyUtils.formatBRL(doc.getTotal()));
257	
258	        doc.setText(text.toString());
259	    }
260	
261	    private void generateInvoice(Document doc) {
262	        doc.setTitle("Fatura de hospedagem");
263	
264	        BigDecimal iss = MoneyUtils.round(doc.getTotal().multiply(ISS_RATE));
265	
266	        StringBuilder text = new StringBuilder();
267	        text.append("Fatura de hospedagem nº ").append(doc.getReservationId()).append("\n");
268	        text.append("Empresa: ").append(doc.getCompanyName());
269	        text.append(" (CNPJ ").append(doc.getCompanyCnpj()).append(")\n");
270	        text.append("Hóspede: ").append(doc.getGuestName()).append("\n");
271	        text.append("Quarto: ").append(doc.getRoomNumber());
272	        text.append(" (").append(doc.getRoomType()).append(")\n");
273	        text.append("Entrada: ").append(doc.getCheckIn().format(PT_DATE_FORMAT));
274	        text.append(" | Saída: ").append(doc.getCheckOut().format(PT_DATE_FORMAT));
275	        text.append(" | ").append(doc.getNights()).append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
276	        text.append("Diárias: ").append(MoneyUtils.formatBRL(doc.getSubtotal())).append("\n");
277	
278	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
279	            text.append("Desconto: ").append(MoneyUtils.formatBRL(doc.getDiscount())).append("\n");
280	        }
281	
282	        text.append("Total: ").append(MoneyUtils.formatBRL(doc.getTotal())).append("\n");
283	        text.append("ISS retido (5%): ").append(MoneyUtils.formatBRL(iss));
284	
285	        doc.setText(text.toString());
286	    }
287	
288	    private void generateBookingReceipt(Document doc) {
289	        doc.setTitle("Booking receipt");
290	
291	        StringBuilder text = new StringBuilder();
292	        text.append("Booking receipt no. ").append(doc.getReservationId()).append("\n");
293	        text.append("Guest: ").append(doc.getGuestName());
294	        text.append(" (passport ").append(doc.getGuestPassport());
295	        text.append(", ").append(doc.getGuestCountry()).append(")\n");
296	        text.append("Room: ").append(doc.getRoomNumber());
297	        text.append(" (").append(doc.getRoomType()).append(")\n");
298	        text.append("Check-in: ").append(doc.getCheckIn().format(EN_DATE_FORMAT));
299	        text.append(" | Check-out: ").append(doc.getCheckOut().format(EN_DATE_FORMAT));
300	        text.append(" | ").append(doc.getNights()).append(doc.getNights() == 1 ? " night" : " nights").append("\n");
301	        text.append("Nights: ").append(MoneyUtils.formatBRLInternational(doc.getSubtotal())).append("\n");
302	
303	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
304	            text.append("Discount: ").append(MoneyUtils.formatBRLInternational(doc.getDiscount())).append("\n");
305	        }
306	
307	        text.append("Total: ").append(MoneyUtils.formatBRLInternational(doc.getTotal()));
308	
309	        doc.setText(text.toString());
310	    }
311	}
