391	import br.com.maralta.model.Reservation;
392	import br.com.maralta.repository.ReservationRepository;
393	import br.com.maralta.repository.RoomRepository;
394	
395	import java.math.BigDecimal;
396	import java.time.LocalDate;
397	import java.time.YearMonth;
398	import java.time.format.DateTimeFormatter;
399	import java.util.List;
400	
401	public class ReportService {
402	
403	    private final ReservationRepository reservationRepository;
404	    private final RoomRepository roomRepository;
405	
406	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
407	
408	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
409	        this.reservationRepository = reservationRepository;
410	        this.roomRepository = roomRepository;
411	    }
412	
413	    public String generateOccupancyReport(LocalDate date) {
414	        StringBuilder csv = new StringBuilder();
415	        csv.append("room,type,reservation,check_in,check_out\n");
416	
417	        List<Reservation> reservations = reservationRepository.findByNight(date);
418	        int totalRooms = roomRepository.findAll().size();
419	
420	        for (Reservation r : reservations) {
421	            csv.append(r.getRoomNumber()).append(",");
422	
423	            var room = roomRepository.findByNumber(r.getRoomNumber()).orElseThrow();
424	            csv.append(room.getType()).append(",");
425	            csv.append(r.getId()).append(",");
426	            csv.append(r.getCheckIn().format(DATE_FORMAT)).append(",");
427	            csv.append(r.getCheckOut().format(DATE_FORMAT)).append("\n");
428	        }
429	
430	        csv.append("total,").append(reservations.size()).append("/").append(totalRooms);
431	
432	        return csv.toString();
433	    }
434	
435	    public String generateRevenueReport(YearMonth month) {
436	        StringBuilder csv = new StringBuilder();
437	        csv.append("reservation,room,check_in,check_out,status,amount\n");
438	
439	        List<Reservation> reservations = reservationRepository.findByMonth(month);
440	        BigDecimal total = BigDecimal.ZERO;
441	
442	        for (Reservation r : reservations) {
443	            BigDecimal amount = r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO);
444	
445	            csv.append(r.getId()).append(",");
446	            csv.append(r.getRoomNumber()).append(",");
447	            csv.append(r.getCheckIn().format(DATE_FORMAT)).append(",");
448	            csv.append(r.getCheckOut().format(DATE_FORMAT)).append(",");
449	            csv.append(r.getStatus()).append(",");
450	            csv.append(String.format("%.2f", amount)).append("\n");
451	
452	            total = total.add(amount);
453	        }
454	
455	        csv.append("total,,,,,").append(String.format("%.2f", total));
456	
457	        return csv.toString();
458	    }
459	}
460	package br.com.maralta.service;
