462	import br.com.maralta.exception.ApiException;
463	import br.com.maralta.model.*;
464	import br.com.maralta.repository.ReservationRepository;
465	import br.com.maralta.repository.RoomRepository;
466	
467	import java.math.BigDecimal;
468	import java.time.LocalDate;
469	import java.time.temporal.ChronoUnit;
470	
471	public class ReservationService {
472	
473	    private final ReservationRepository reservationRepository;
474	    private final RoomRepository roomRepository;
475	    private final PricingService pricingService;
476	    private final DocumentService documentService;
477	    private final EmailService emailService;
478	
479	    public ReservationService(
480	            ReservationRepository reservationRepository,
481	            RoomRepository roomRepository,
482	            PricingService pricingService,
483	            DocumentService documentService,
484	            EmailService emailService) {
485	        this.reservationRepository = reservationRepository;
486	        this.roomRepository = roomRepository;
487	        this.pricingService = pricingService;
488	        this.documentService = documentService;
489	        this.emailService = emailService;
490	    }
491	
492	    public Reservation createReservation(Reservation reservation) {
493	        validate(reservation);
494	
495	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
496	            .orElseThrow(ApiException::roomNotFound);
497	
498	        if (reservation.getGuests() > room.getCapacity()) {
499	            throw ApiException.capacityExceeded();
500	        }
501	
502	        checkAvailability(reservation.getRoomNumber(), reservation.getCheckIn(),
503	                         reservation.getCheckOut(), null);
504	
505	        calculatePricing(reservation, room);
506	
507	        return reservationRepository.save(reservation);
508	    }
509	
510	    public Reservation getReservation(Long id) {
511	        return reservationRepository.findById(id)
512	            .orElseThrow(ApiException::reservationNotFound);
513	    }
514	
515	    public Reservation confirmReservation(Long id) {
516	        Reservation reservation = getReservation(id);
517	
518	        if (!reservation.canConfirm()) {
519	            throw ApiException.operationNotAllowed("Cannot confirm reservation in current status");
520	        }
521	
522	        reservation.setStatus(ReservationStatus.CONFIRMED);
523	        reservation.setAmountPaid(reservation.getTotal());
524	        reservationRepository.save(reservation);
525	
526	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
527	        Document document = documentService.generateDocument(reservation, room);
528	        emailService.sendConfirmationEmail(reservation.getGuestEmail(), reservation.getGuestName(), document);
529	
530	        return reservation;
531	    }
532	
533	    public Reservation checkIn(Long id) {
534	        Reservation reservation = getReservation(id);
535	
536	        if (!reservation.canCheckIn()) {
537	            throw ApiException.operationNotAllowed("Cannot check-in reservation in current status");
538	        }
539	
540	        reservation.setStatus(ReservationStatus.CHECKED_IN);
541	        return reservationRepository.save(reservation);
542	    }
543	
544	    public Document checkOut(Long id) {
545	        Reservation reservation = getReservation(id);
546	
547	        if (!reservation.canCheckOut()) {
548	            throw ApiException.operationNotAllowed("Cannot check-out reservation in current status");
549	        }
550	
551	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
552	        reservationRepository.save(reservation);
553	
554	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
555	        return documentService.generateDocument(reservation, room);
556	    }
557	
558	    public Reservation cancelReservation(Long id) {
559	        Reservation reservation = getReservation(id);
560	
561	        if (!reservation.canCancel()) {
562	            throw ApiException.operationNotAllowed("Cannot cancel reservation in current status");
563	        }
564	
565	        reservation.setStatus(ReservationStatus.CANCELLED);
566	
567	        BigDecimal refundAmount = calculateRefund(reservation);
568	        reservation.setRefund(refundAmount);
569	
570	        return reservationRepository.save(reservation);
571	    }
572	
573	    public Document getDocument(Long id) {
574	        Reservation reservation = getReservation(id);
575	
576	        if (!reservation.isPaid()) {
577	            throw ApiException.operationNotAllowed("Document only available for paid reservations");
578	        }
579	
580	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
581	        return documentService.generateDocument(reservation, room);
582	    }
583	
584	    private void validate(Reservation reservation) {
585	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
586	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
587	            throw ApiException.invalidRequest("Check-out must be after check-in");
588	        }
589	
590	        if (reservation.getGuests() < 1) {
591	            throw ApiException.invalidRequest("At least one guest is required");
592	        }
593	
594	        if (reservation.getIdentification() == null || !reservation.getIdentification().isValid()) {
