606	    private void calculatePricing(Reservation reservation, Room room) {
607	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
608	        reservation.setNights(nights);
609	
610	        BigDecimal subtotal = pricingService.calculateSubtotal(room, reservation.getCheckIn(), reservation.getCheckOut());
