346	
347	import java.math.BigDecimal;
348	import java.time.LocalDate;
349	
350	public class PricingService {
351	
352	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
353	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
354	
355	    public BigDecimal calculateNightlyRate(Room room, LocalDate night) {
356	        BigDecimal baseRate = room.getNightlyRate();
357	
358	        if (SeasonUtils.isHighSeason(night)) {
359	            baseRate = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
360	        }
361	
362	        return MoneyUtils.round(baseRate);
363	    }
364	
365	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
366	        BigDecimal subtotal = BigDecimal.ZERO;
367	
368	        LocalDate current = checkIn;
369	        while (current.isBefore(checkOut)) {
370	            BigDecimal nightlyRate = calculateNightlyRate(room, current);
371	            subtotal = subtotal.add(nightlyRate);
372	            current = current.plusDays(1);
373	        }
374	
375	        return MoneyUtils.round(subtotal);
376	    }
377	
378	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
379	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
380	            return MoneyUtils.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
381	        }
382	        return BigDecimal.ZERO;
383	    }
384	
385	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
386	        return MoneyUtils.round(subtotal.subtract(discount));
387	    }
388	}
