558	    public Reservation cancelReservation(Long id) {
559	        Reservation reservation = getReservation(id);
560	
561	        if (!reservation.canCancel()) {
562	            throw ApiException.operationNotAllowed("Cannot cancel reservation in current status");
563	        }
564	
565	        reservation.setStatus(ReservationStatus.CANCELLED);
566	
567	        BigDecimal refundAmount = calculateRefund(reservation);
568	        reservation.setRefund(refundAmount);
569	
570	        return reservationRepository.save(reservation);
571	    }
572	
573	    public Document getDocument(Long id) {
574	        Reservation reservation = getReservation(id);
575	
576	        if (!reservation.isPaid()) {
577	            throw ApiException.operationNotAllowed("Document only available for paid reservations");
578	        }
579	
580	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
581	        return documentService.generateDocument(reservation, room);
582	    }
583	
584	    private void validate(Reservation reservation) {
585	        if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
586	            reservation.getCheckOut().equals(reservation.getCheckIn())) {
587	            throw ApiException.invalidRequest("Check-out must be after check-in");
588	        }
589	
590	        if (reservation.getGuests() < 1) {
591	            throw ApiException.invalidRequest("At least one guest is required");
592	        }
593	
594	        if (reservation.getIdentification() == null || !reservation.getIdentification().isValid()) {
595	            throw ApiException.invalidRequest("Invalid guest identification");
596	        }
597	    }
598	
599	    private void checkAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
600	        var conflicting = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, excludeId);
601	        if (!conflicting.isEmpty()) {
602	            throw ApiException.roomUnavailable();
603	        }
604	    }
605	
606	    private void calculatePricing(Reservation reservation, Room room) {
607	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
608	        reservation.setNights(nights);
609	
610	        BigDecimal subtotal = pricingService.calculateSubtotal(room, reservation.getCheckIn(), reservation.getCheckOut());
611	        reservation.setSubtotal(subtotal);
612	
613	        BigDecimal discount = pricingService.calculateDiscount(subtotal, reservation.getRatePlan());
614	        reservation.setDiscount(discount);
615	
616	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
617	        reservation.setTotal(total);
618	    }
619	
620	    private BigDecimal calculateRefund(Reservation reservation) {
621	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
622	            return BigDecimal.ZERO;
623	        }
624	
625	        return reservation.getAmountPaid();
626	    }
627	}

