102	    private Reservation insert(Reservation reservation) {
103	        String sql = """
104	            INSERT INTO reservations (
105	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
106	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
107	                nights, subtotal, discount, total, status, amount_paid, refund
108	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
109	            RETURNING id
110	        """;
111	
112	        try (Connection conn = dataSource.getConnection();
113	             PreparedStatement stmt = conn.prepareStatement(sql)) {
114	
115	            setReservationParameters(stmt, reservation);
116	
117	            try (ResultSet rs = stmt.executeQuery()) {
118	                if (rs.next()) {
119	                    reservation.setId(rs.getLong("id"));
120	                }
121	            }
122	
123	        } catch (Exception e) {
124	            throw new RuntimeException("Failed to insert reservation", e);
125	        }
126	
127	        return reservation;
128	    }
129	
130	    private Reservation update(Reservation reservation) {
131	        String sql = """
132	            UPDATE reservations SET
133	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?, company_cnpj = ?,
134	                company_name = ?, guest_passport = ?, guest_country = ?, check_in = ?,
135	                check_out = ?, guests = ?, rate_plan = ?, nights = ?, subtotal = ?,
136	                discount = ?, total = ?, status = ?, amount_paid = ?, refund = ?
137	            WHERE id = ?
138	        """;
139	
140	        try (Connection conn = dataSource.getConnection();
141	             PreparedStatement stmt = conn.prepareStatement(sql)) {
142	
143	            setReservationParameters(stmt, reservation);
144	            stmt.setLong(20, reservation.getId());
145	            stmt.executeUpdate();
146	
147	        } catch (Exception e) {
148	            throw new RuntimeException("Failed to update reservation", e);
149	        }
150	
151	        return reservation;
152	    }
153	
154	    private void setReservationParameters(PreparedStatement stmt, Reservation r) throws SQLException {
155	        GuestIdentification id = r.getIdentification();
156	
157	        stmt.setString(1, r.getRoomNumber());
158	        stmt.setString(2, r.getGuestName());
159	        stmt.setString(3, r.getGuestEmail());
160	        stmt.setString(4, id != null ? id.getGuestCpf() : null);
161	        stmt.setString(5, id != null ? id.getCompanyCnpj() : null);
162	        stmt.setString(6, id != null ? id.getCompanyName() : null);
163	        stmt.setString(7, id != null ? id.getGuestPassport() : null);
164	        stmt.setString(8, id != null ? id.getGuestCountry() : null);
165	        stmt.setDate(9, Date.valueOf(r.getCheckIn()));
166	        stmt.setDate(10, Date.valueOf(r.getCheckOut()));
167	        stmt.setInt(11, r.getGuests());
168	        stmt.setString(12, r.getRatePlan().name());
169	        stmt.setInt(13, r.getNights());
170	        stmt.setBigDecimal(14, r.getSubtotal());
171	        stmt.setBigDecimal(15, r.getDiscount());
172	        stmt.setBigDecimal(16, r.getTotal());
173	        stmt.setString(17, r.getStatus().name());
174	        stmt.setBigDecimal(18, r.getAmountPaid());
175	        stmt.setBigDecimal(19, r.getRefund());
176	    }
