178	    public Optional<Reservation> findById(Long id) {
179	        String sql = "SELECT * FROM reservations WHERE id = ?";
180	
181	        try (Connection conn = dataSource.getConnection();
182	             PreparedStatement stmt = conn.prepareStatement(sql)) {
183	
184	            stmt.setLong(1, id);
185	
186	            try (ResultSet rs = stmt.executeQuery()) {
187	                if (rs.next()) {
188	                    return Optional.of(mapReservation(rs));
189	                }
190	            }
191	
192	        } catch (Exception e) {
193	            throw new RuntimeException("Failed to fetch reservation", e);
194	        }
195	
196	        return Optional.empty();
197	    }
