199	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
200	        String sql = """
201	            SELECT * FROM reservations
202	            WHERE room_number = ?
203	            AND status != 'CANCELLED'
204	            AND check_in < ?
205	            AND check_out > ?
206	            AND (? IS NULL OR id != ?)
207	        """;
208	
209	        List<Reservation> reservations = new ArrayList<>();
210	
211	        try (Connection conn = dataSource.getConnection();
212	             PreparedStatement stmt = conn.prepareStatement(sql)) {
213	
214	            stmt.setString(1, roomNumber);
215	            stmt.setDate(2, Date.valueOf(checkOut));
216	            stmt.setDate(3, Date.valueOf(checkIn));
217	            stmt.setObject(4, excludeId);
218	            stmt.setObject(5, excludeId);
219	
220	            try (ResultSet rs = stmt.executeQuery()) {
221	                while (rs.next()) {
222	                    reservations.add(mapReservation(rs));
223	                }
224	            }
225	
226	        } catch (Exception e) {
227	            throw new RuntimeException("Failed to check room availability", e);
228	        }
229	
230	        return reservations;
231	    }
