233	    public List<Reservation> findByNight(LocalDate night) {
234	        String sql = """
235	            SELECT * FROM reservations
236	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
237	            AND check_in <= ?
238	            AND check_out > ?
239	            ORDER BY room_number
240	        """;
241	
242	        List<Reservation> reservations = new ArrayList<>();
243	
244	        try (Connection conn = dataSource.getConnection();
245	             PreparedStatement stmt = conn.prepareStatement(sql)) {
246	
247	            stmt.setDate(1, Date.valueOf(night));
248	            stmt.setDate(2, Date.valueOf(night));
249	
250	            try (ResultSet rs = stmt.executeQuery()) {
251	                while (rs.next()) {
252	                    reservations.add(mapReservation(rs));
253	                }
254	            }
255	
256	        } catch (Exception e) {
257	            throw new RuntimeException("Failed to fetch reservations by night", e);
258	        }
259	
260	        return reservations;
