263	    public List<Reservation> findByMonth(YearMonth month) {
264	        String sql = """
265	            SELECT * FROM reservations
266	            WHERE EXTRACT(YEAR FROM check_in) = ?
267	            AND EXTRACT(MONTH FROM check_in) = ?
268	            AND (amount_paid > 0 OR refund > 0)
269	            ORDER BY check_in, id
270	        """;
271	
272	        List<Reservation> reservations = new ArrayList<>();
273	
274	        try (Connection conn = dataSource.getConnection();
275	             PreparedStatement stmt = conn.prepareStatement(sql)) {
276	
277	            stmt.setInt(1, month.getYear());
278	            stmt.setInt(2, month.getMonthValue());
279	
280	            try (ResultSet rs = stmt.executeQuery()) {
281	                while (rs.next()) {
282	                    reservations.add(mapReservation(rs));
283	                }
284	            }
285	
286	        } catch (Exception e) {
287	            throw new RuntimeException("Failed to fetch reservations by month", e);
288	        }
289	
290	        return reservations;
291	    }
