504	        Month month = date.getMonth();
505	        int day = date.getDayOfMonth();
506	
507	        if (month == Month.JULY) {
508	            return true;
509	        }
510	
511	        if (month == Month.DECEMBER && day >= 15) {
512	            return true;
513	        }
514	
515	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
516	            return true;
517	        }
518	
519	        return false;
