102	    private Reservation insert(Reservation reservation) {
103	        String sql = """
104	            INSERT INTO reservations (
105	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
106	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
107	                nights, subtotal, discount, total, status, amount_paid, refund
108	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
109	            RETURNING id
110	        """;
111	
112	        try (Connection conn = dataSource.getConnection();
113	             PreparedStatement stmt = conn.prepareStatement(sql)) {
114	
115	            setReservationParameters(stmt, reservation);
116	
117	            try (ResultSet rs = stmt.executeQuery()) {
118	                if (rs.next()) {
119	                    reservation.setId(rs.getLong("id"));
120	                }
121	            }
122	
123	        } catch (Exception e) {
124	            throw new RuntimeException("Failed to insert reservation", e);
125	        }
126	
127	        return reservation;
128	    }
