130	    private Reservation update(Reservation reservation) {
131	        String sql = """
132	            UPDATE reservations SET
133	                room_number = ?, guest_name = ?, guest_email = ?, guest_cpf = ?, company_cnpj = ?,
134	                company_name = ?, guest_passport = ?, guest_country = ?, check_in = ?,
135	                check_out = ?, guests = ?, rate_plan = ?, nights = ?, subtotal = ?,
136	                discount = ?, total = ?, status = ?, amount_paid = ?, refund = ?
137	            WHERE id = ?
138	        """;
139	
140	        try (Connection conn = dataSource.getConnection();
141	             PreparedStatement stmt = conn.prepareStatement(sql)) {
142	
143	            setReservationParameters(stmt, reservation);
144	            stmt.setLong(20, reservation.getId());
145	            stmt.executeUpdate();
146	
147	        } catch (Exception e) {
148	            throw new RuntimeException("Failed to update reservation", e);
149	        }
150	
151	        return reservation;
152	    }
