199	    public List<Reservation> findConflicting(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) {
200	        String sql = """
201	            SELECT * FROM reservations
202	            WHERE room_number = ?
203	            AND status != 'CANCELLED'
204	            AND check_in < ?
205	            AND check_out > ?
206	            AND (? IS NULL OR id != ?)
207	        """;
208	
209	        List<Reservation> reservations = new ArrayList<>();
210	
211	        try (Connection conn = dataSource.getConnection();
212	             PreparedStatement stmt = conn.prepareStatement(sql)) {
