263	    public List<Reservation> findByMonth(YearMonth month) {
264	        String sql = """
265	            SELECT * FROM reservations
266	            WHERE EXTRACT(YEAR FROM check_in) = ?
267	            AND EXTRACT(MONTH FROM check_in) = ?
268	            AND (amount_paid > 0 OR refund > 0)
269	            ORDER BY check_in, id
270	        """;
271	
272	        List<Reservation> reservations = new ArrayList<>();
