293	    private Reservation mapReservation(ResultSet rs) throws SQLException {
294	        Reservation reservation = new Reservation();
295	        reservation.setId(rs.getLong("id"));
296	        reservation.setRoomNumber(rs.getString("room_number"));
297	        reservation.setGuestName(rs.getString("guest_name"));
298	        reservation.setGuestEmail(rs.getString("guest_email"));
299	
300	        GuestIdentification identification = new GuestIdentification();
301	        identification.setGuestCpf(rs.getString("guest_cpf"));
302	        identification.setCompanyCnpj(rs.getString("company_cnpj"));
303	        identification.setCompanyName(rs.getString("company_name"));
304	        identification.setGuestPassport(rs.getString("guest_passport"));
305	        identification.setGuestCountry(rs.getString("guest_country"));
306	        reservation.setIdentification(identification);
307	
308	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
309	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
310	        reservation.setGuests(rs.getInt("guests"));
311	        reservation.setRatePlan(RatePlan.valueOf(rs.getString("rate_plan")));
312	        reservation.setNights(rs.getInt("nights"));
313	        reservation.setSubtotal(rs.getBigDecimal("subtotal"));
314	        reservation.setDiscount(rs.getBigDecimal("discount"));
315	        reservation.setTotal(rs.getBigDecimal("total"));
316	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
317	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
318	
319	        BigDecimal refund = rs.getBigDecimal("refund");
320	        reservation.setRefund(rs.wasNull() ? null : refund);
321	
322	        return reservation;
323	    }
324	}
